INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'RAMP-AUDIT-BR', 'REF-01007', NULL, 1, 0, '[]', '[backward 2026-09-25 04:35] PASS RAN ON ADMISSION against the publisher''s Crossref deposit (32 references). DERIVE THE YIELD: python3 scripts/research/mining_screen.py --ref REF-01007 --compare. The slope screens score 0 and that is the documented audit blind spot, not a thin list: reading the titles and four abstracts surfaced two audits worth staging (candidates staged under exec 95: Martins 2016, NBR 9050 slope compliance in 90 Brazilian units; Mudrick 2012, 2,389 California facilities). FORWARD NOT RUN: REF-01007 is T3 (clinical, lower_control) and R2''s mandatory mining scope is confirmed T1-T2 anchors; recorded here in notes rather than as a deferral so the executed backward pass is not overwritten.', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'RAMP-HIST-02', 'REF-01008', NULL, 1, 0, '[]', '[backward 2026-09-25 04:49] PASS RAN ON ADMISSION against the printed reference list, transcribed from the rendered page and persisted as a derived artefact (75c991f61483c1ac.json). DERIVE THE YIELD: python3 scripts/research/mining_screen.py --ref REF-01008 --compare. Five entries: Dixon 1957 (candidate 110), ANSI A117.1 1977 (a code), Walter 1971 (candidate 109), Herms 1976 and Snyder 1971 (both off parameter 3). No new candidate. FORWARD NOT RUN: T3 grey report with no DOI, and R2''s mandatory mining scope is T1-T2; recorded in notes rather than as a deferral so the executed backward pass is not overwritten.', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
