heir Right to Health?', NULL, NULL, NULL, 'en', 'language field ''eng'' in the persisted Europe PMC core record, and the retrieved JATS full text is English', NULL, NULL, NULL, NULL, NULL, 0, 'International Journal of Environmental Research and Public Health', NULL, '18', '6', NULL, NULL, NULL, 'MDPI AG', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.3390/ijerph18062953', '33805773', NULL, NULL, NULL, 'https://europepmc.org/articles/PMC7999795', '2026-09-25', NULL, NULL, 3, 'clinical', 'BR', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-25 04:33', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'crossref', NULL, 1, NULL, '2953', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'lower_control', 'captured', 'mined', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-01008', 'report', NULL, 0, NULL, NULL, 0, NULL, 1980, NULL, 'Provisions for Elderly and Handicapped Pedestrians. Volume 3: The Development and Evaluation of Countermeasures', NULL, NULL, NULL, 'en', 'read on the rendered Technical Report Documentation Page (zero-based page index 2) and throughout the text', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Federal Highway Administration, Offices of Research and Development', 'Washington, D.C.', NULL, NULL, NULL, NULL, 'FHWA-RD-79-3', 'Georgia Institute of Technology, College of Architecture, Pedestrian Research Laboratory', NULL, NULL, NULL, NULL, NULL, NULL, 'https://archive.org/details/provisionsforeld00temp_0', '2026-09-25', NULL, NULL, 3, 'grey', 'US', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'NO-MATCH', NULL, NULL, 1, 'US federal contract research report (FHWA contract DOT-FH-11-8504, Georgia Tech Pedestrian Research Laboratory), final report dated May 1980, distributed through NTIS; not peer-reviewed; no DOI (Crossref bibliographic query persisted this batch returns no record for it); digitised by the National Transportation Library on Internet Archive under CC BY-NC-ND 3.0.', NULL, NULL, NULL, NULL, NULL, '2026-09-25 04:46', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'mined', NULL, NULL, NULL, NULL, 'CLOSED', 'direct-render', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-044', 'SW', 'P2', 'OPEN', 'governance', NULL, 'A KNOWN-WRONG AUTHOR ROW THAT NO SANCTIONED WRITER CAN CORRECT. REF-01002''s fourth author is stored as ''Weiner, Jerome M.'' (from TRID, a record GAP-026 already showed wrong on its publisher field). The publisher''s own table of contents for J Architectural and Planning Research 26(2), Summer 2009 -- lockescience.com/TOC262.pdf, persisted in the batch-20 retrieval log as 07da0016d338f0f8.pdf, a born-digital text PDF (no page images; embedded Times New Roman), rendered and read -- prints ''Jerome M. Welner''. THE ROW CANNOT BE FIXED: correct-source REFUSES DOI-less sources (''no DOI, so no payload can be keyed to it''), its payload map reads only Crossref-shaped JSON, and it is the only verb that rewrites an admitted source''s author rows (add-source writes them once, at admission); CLAUDE.md section 4 forbids hand SQL on a table the CLI should reach. That is a coverage bug, not a licence to bypass. WHY IT MATTERS MORE THAN ONE LETTER: the corpus''s signature failure (2026-08-19) was a wrong author list that six gates passed; here the right name is in hand, persisted and rendered, and the wrong one stays because the correction path only trusts DOI-keyed payloads. Grey and pre-DOI sources -- REF-01005, REF-01008, every T5/T6 row -- have the same exposure. WHAT WOULD CLOSE IT: let correct-source take a persisted non-Crossref artefact (a publisher TOC, a title page render) with an explicit field map and its own verify-authors comparison, then correct REF-01002 through it. Derive the row''s state rather than trusting this text: select position, last_name, first_name from evidence_source_authors where ref_id=''REF-01002''.', '2026-09-25 05:02', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 05:02', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (92, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', 'Europe PMC REST search, resultType=lite, pageSize=100: ("accessibility audit" OR "access audit") AND ramp AND (gradient OR slope) AND (participatory OR "disabled people''s organisation" OR "disabled persons organisation" OR "organisation of persons with disabilities" OR "co-researchers" OR "peer researchers")', '["accessibility audit","access audit","ramp","gradient","slope","participatory","disabled people''s organisation","disabled persons organisation","organisation of persons with disabilities","co-researchers","peer researchers"]', 'europepmc', 'scoping', 'none', 2, 2, 0, 'partial', NULL, NULL, 0, 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:27', 'hitCount 2, read from the persisted payload (retrieval-log/<session>/9c93761f45476b62.json), BELOW the predicted 10-120. The known positive came back: result 1 is REF-01006 (Raghuram et al. 2026, already admitted by batch 19), so the query SHAPE is sound and the narrowness is real rather than a malformed AND-chain (R14). Result 2 is Mora et al. 2017, Sensors, a smart-city sensing system for urban accessibility monitoring -- an engineering system paper, not an audit of buildings and not co-produced; screened out on title. NO NEW Co-1 SOURCE. The exact phrases "accessibility audit"/"access audit" were judged the likeliest single constraint doing the narrowing, which is why Q1b (next exec) relaxes them.', 0, 'Committed in scratchpad/<session>/query-priors.md (aa3207de) BEFORE this query fired. hitCount between 10 and 120, p~0.6 (full-text AND of five concepts is narrow but "participatory" is common). At least one on-topic result not already in the corpus that is BOTH co-produced with disabled people AND reports a measured ramp gradient: p~0.35. REF-01006 itself should appear (it is PMC-deposited and matches every term) -- p~0.8; if it does not, the query shape is suspect, not the literature (R14). Most hits will be health-facility audits in LMICs, same cluster as candidates 123/124, p~0.6.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (93, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', 'Europe PMC REST search, resultType=lite, pageSize=100: audit AND ramp AND (gradient OR slope) AND ("persons with disabilities" OR "people with disabilities" OR "disabled people") AND (participatory OR "user-led" OR "co-production" OR "co-researchers" OR "peer researchers" OR "disabled people''s organisation" OR "organisation of persons with disabilities")', '["audit","ramp","gradient","slope","persons with disabilities","people with disabilities","disabled people","participatory","user-led","co-production","co-researchers","peer researchers","disabled people''s organisation","organisation of persons with disabilities"]', 'europepmc', 'scoping', 'none', 21, 21, 0, 'partial', NULL, NULL, 0, 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:27', 'hitCount 21, read from the persisted payload (5bac867ff07f9895.json). THE PRIOR MIS-DESCRIBED ITS OWN QUERY: query-priors.md says Q1b "relaxes that one term and nothing else", but Q1b ALSO adds a disability-population clause and swaps the co-production OR-set (drops "disabled persons organisation", adds user-led / co-production). So Q1 vs Q1b does NOT isolate the audit phrase; it is two changes, and the jump from 2 to 21 cannot be attributed to either alone. Recorded rather than smoothed over. SCREEN: 21 titles; 13 are conference abstract books, proceedings or off-topic (COVID athletes, nutrition, schizophrenia, haematology) -- full-text search matching a word soup, screened out on title. Abstracts fetched for 4 (persisted 5a34679594815519.json); full text fetched for 1 (18ef7d575e63330c.xml). ONE NEW Co-1-ADJACENT AUDIT FOUND AND STAGED, NOT ADMITTED: Mactaggart et al. 2024, Int J Equity Health, doi 10.1186/s12939-024-02314-0 (PMC11562328), Luuka District, Uganda -- the Disability Awareness Checklist adapted in three rounds WITH eight Ugandan youth researchers with disabilities, who then co-facilitated the audits in pairs (one disabled youth researcher, one non-disabled peer). It MEASURES ramp slope ("For long ramps (over 2 m), 2-3 measurements were taken at various points along the length, and the steepest angle was recorded") and reports a FAILURE: "of three facilities with ramps, all reached the minimum required width ... but two were too steep and none had handrails, meaning all failed the overall accessibility criteria for a ramp." The numeric slope criterion lives in Supplementary File Appendix 2, NOT retrieved, so no gradient value is in hand -- staged for a batch that can read the appendix. The warrant is co-production of the INSTRUMENT and co-facilitation of the MEASUREMENT by disabled youth researchers; the authorship and analysis are academic (LSHTM/MRC), so a Co-1 tier must be decided from the full text against D-0178, not assumed from this note. Also screened in: Obrusnikova et al. 2026 (US park audit, curb-ramp completeness inconsistent -- also a Q2 hit, staged once); REF-01006 recurred (already admitted). Screened out on abstract: Soner 2026 (nursing students evaluating a campus, a pedagogy study, not disabled-led); Seekins 2022 (Google Street View remote access scoring, a method paper, no gradient); Perry 2021 (qualitative park experiences of older adults with disability -- lived experience, but no ramp-gradient claim). harm_finding=1 on the Mactaggart ramp failure.', 1, 'Appended to scratchpad/<session>/query-priors.md and committed (26ae1dc1) after Q1/Q2 returned and BEFORE this query fired; recorded there as not part of the original plan. hitCount 10-150, p~0.6. At least one NEW co-produced audit that records a ramp gradient: p~0.25. If Q1b returns only REF-01006 plus off-topic hits, the Co-1 audit stratum on ramp gradient is genuinely thin in Europe PMC OA full text -- an INDEX-bounded absence, not a literature-wide one.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (94, 'accessible-circulation-geometry', NULL, 'EN', 2, 'sr_meta', 'intrinsic', 'Europe PMC REST search, resultType=lite, pageSize=100: ("systematic review" OR "scoping review") AND ("accessibility audit" OR "physical accessibility" OR "architectural barriers") AND ramp AND (gradient OR slope OR incline)', '["systematic review","scoping review","accessibility audit","physical accessibility","architectural barriers","ramp","gradient","slope","incline"]', 'europepmc', 'scoping', 'none', 8, 8, 0, 'partial', NULL, NULL, 0, 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:28', 'hitCount 8, read from the persisted payload (bbf51a11601dc95b.json), BELOW the predicted 20-300. NO T2 SOURCE: no systematic review or meta-analysis that pools ramp-gradient compliance was returned, so the T2 half of the R1 leg is a completed null for this index and this query shape, not a claim about the literature. The two reviews returned are both below T2 by tier-system 2/9: Miller, Prasai and Morrison 2026 (Glob Health Action) is a RAPID SCOPING review of accessibility FRAMEWORKS for public recreational spaces -- a map of instruments, not of findings -- and Edwards et al. 2026 (Research Square preprint) is a RAPID review of active-travel infrastructure (kerbs, bus stops, tactile paving), with no ramp-gradient synthesis in its abstract. Four of the eight are abstract books or off-topic (Cochrane stroke rehabilitation, SGIM abstracts, GSA abstracts, wheelchair route-planning instrumentation). TWO PRIMARY AUDITS SURFACED AND ARE STAGED, both of the document type batch 19 flagged as the title-screen false negative: Campillay-Campillay et al. 2022 (IJERPH, doi 10.3390/ijerph191912439), an external-audit cross-sectional study of 18 primary health care centres in Atacama, Chile, reporting architectural-aspect compliance 63.9 percent against a 70 percent lower control limit -- a new jurisdiction for the audit cluster, whether a ramp-gradient item is itself reported is not established from the abstract; and Obrusnikova et al. 2026 (IJERPH, doi 10.3390/ijerph23010139), a statewide audit of 50 Delaware parks reporting "Curb-ramp completeness was inconsistent" -- whether curb-ramp SLOPE was measured is not established from the abstract. harm_finding=1: both report inadequacy. P7b (a T2 review tabulating ramp-gradient compliance) is NOT confirmed.', 1, 'Committed in scratchpad/<session>/query-priors.md (aa3207de) BEFORE this query fired. hitCount between 20 and 300, p~0.6. At least one review whose own synthesis reports ramp-gradient compliance or a ramp-gradient outcome across included studies: p~0.35. A review that is systematic (appraised, T2 sr_meta) rather than scoping (T3 per tier-system 2/9): p~0.4 conditional on one being found. Candidate 114 may recur and must not be double-staged (R9).');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (95, 'accessible-circulation-geometry', NULL, 'EN', 3, 'clinical', 'lower_control', 'BACKWARD MINING PASS over REF-01007 (Pinto, Koptcke, David and Kuper 2021, doi 10.3390/ijerph18062953): the publisher-deposited Crossref reference list (32 entries), persisted as retrieval-log/<session>/265e92157feb3c35.json; screened with python3 scripts/research/mining_screen.py --ref REF-01007 --compare, then every title read by eye because a title screen is blind to audits.', NULL, 'crossref-deposit', 'scoping', 'backward', 32, 32, 0, 'partial', NULL, NULL, 0, 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', 'DERIVE THE SCREEN YIELD, DO NOT QUOTE IT: python3 scripts/research/mining_screen.py --ref REF-01007 --compare (slope-strict and slope-strict-plus-motion both 0 on this run; slope-loose fires on the accessibility stem). THE ZERO IS THE KNOWN BLIND SPOT, NOT A THIN LIST: reading the 32 titles and then fetching four abstracts (persisted b7b928f29b468566.json) found the audit literature a title screen cannot see. STAGED: Martins et al. 2016 (Ciencia e Saude Coletiva, doi 10.1590/1413-812320152110.20052016), 90 Family Health Units in Joao Pessoa audited against ABNT NBR 9050 -- its abstract reports ''only 47.8% have a wheelchair ramp, of these 30.0% have maximum slope'', the first MEASURED-SLOPE compliance figure this pass has seen, wording ambiguous in translation; Mudrick et al. 2012 (Disability and Health Journal, doi 10.1016/j.dhjo.2012.02.002), 2,389 California primary care facilities on a 55-item on-site instrument -- exterior access ''generally met the access criteria'', whether ramp slope is an item is not in the abstract. NOT STAGED, read and set aside: Nischith, Bhargava and Akshaya 2018 (J Family Med Prim Care, 67 PHCs in Dakshina Kannada, AIC checklist) reports ramp PRESENCE (60 of 67) in its abstract, the same shape as REF-01007; Frost et al. 2015 (JRRD, 30 clinics, ADA site assessments) reports restrooms and exam rooms, not ramps. harm_finding=1: every audit read reports inadequacy.', 1, 'NONE RECORDED BEFORE THE PASS WAS READ, and this field says so rather than inventing one. The per-query priors file covers the Co-1/T2 leg only; this pass was run on admission without a written prior. The only relevant pre-registered statement is batch 19''s own warning, carried into priors.md P1: an accessibility audit tabulates gradients while naming no geometry in its title, so slope-strict on an audit''s reference list is expected to be blind.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (96, 'accessible-circulation-geometry', NULL, 'EN', 3, 'clinical', 'lower_control', 'FULL-TEXT RETRIEVAL LADDER for candidate 123 (Garg, Talwar, Garg and Bhandari 2024, doi 10.1016/j.mjafi.2022.10.011), nine requests: (1) api.crossref.org/works/10.1016/j.mjafi.2022.10.011 (2) Europe PMC search DOI core (3) ebi.ac.uk/europepmc/webservices/rest/PMC11116980/fullTextXML (4) eutils efetch db=pmc id=11116980 (5) pmc.ncbi.nlm.nih.gov/articles/PMC11116980/ (6) pmc.ncbi.nlm.nih.gov/articles/PMC11116980/pdf/ (7) europepmc.org/backend/ptpmcrender.fcgi?accid=PMC11116980&blobtype=pdf (8) www.sciencedirect.com/science/article/pii/S0377123722001952 (9) api.openalex.org/works/doi:10.1016/j.mjafi.2022.10.011, plus an Unpaywall lookup.', NULL, 'multi-repository', 'scoping', 'none', 1, 1, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:37', 'BODY UNREACHABLE FROM THIS ENVIRONMENT BY EVERY ROUTE TRIED; ABSTRACT AND METADATA RETRIEVED. results_found=1 is the one record (the article) located; it could not be read past its abstract. Outcomes, each persisted: Crossref 200; Europe PMC core 200 (abstract); Europe PMC fullTextXML HTTP 500; NCBI efetch 200 but front matter only, with the comment ''The publisher of this article does not allow downloading of the full text in XML form'' and pmc-prop-open-access ''no''; PMC article page and PMC /pdf/ both a reCAPTCHA interstitial; Europe PMC PDF render 403 (Cloudflare); ScienceDirect 403 (Cloudflare error 1000); Unpaywall and OpenAlex both name PMC as the only location. So the item is FREE-TO-READ, not OA-licensed, and the free copy sits behind a bot check. That is a correction to batch 19 and to the runbook, both of which called it retrievable here. Not admitted; candidate 123 re-described accordingly. The Unpaywall request carried the email the project''s earlier Unpaywall calls used, which is the user''s own address -- noted so it is not repeated.', 1, 'No retrieval-specific prior was written. priors.md P1 assumed the body would be readable, because batch 19 and the runbook both called this item open access and retrievable; P1a predicted p=0.7 that it reports a ramp-gradient compliance figure. That prior is now untestable rather than tested.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (97, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'BACKWARD MINING PASS over REF-01008 (Templer 1980, FHWA-RD-79-3 Vol. 3). Not an API query: no DOI and no Crossref deposit. The reference list (printed page 299, zero-based index 318) was rendered with page_image.py, transcribed from the image and persisted as a DERIVED artefact, retrieval-log/<session>/75c991f61483c1ac.json; scored with python3 scripts/research/mining_screen.py --ref REF-01008 --compare.', NULL, 'pdf-bibliography', 'scoping', 'backward', 5, 5, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:49', 'THE WHOLE REFERENCE LIST IS FIVE ENTRIES AND NONE IS NEW. DERIVE: python3 scripts/research/mining_screen.py --ref REF-01008 --compare (provenance READ). (1) Dixon, Charles E., 1957 Illinois PhD dissertation -- already candidate 110, whose author is contested with REF-01005''s ''Elmer, C.D.''; this list adds nothing to settle it. (2) ANSI A117.1, printed with a 1977 date and a Syracuse University imprint -- the standard REF-01005 was commissioned to improve; a code, not a study. (3) Walter, Felix, Four Architectural Movement Studies for the Wheelchair and ''Ambuland'' Disabled, DLF, London, 1971 -- already candidate 109, exhausted under the 2026-09-25 owner ruling. (4) Herms, Elias and Robbins 1976, guidestrips for visually handicapped pedestrians -- tactile guidance, off parameter 3. (5) Snyder and Knoblauch 1971, pedestrian safety countermeasures -- vehicle conflict, off parameter 3. NO CANDIDATE STAGED: the two on-parameter entries are already staged and the other three are off it. FORWARD NOT RUN: no citation index holds a 1980 FHWA report as a citable node here, and R2''s mandatory scope is T1-T2.', 0, 'No per-pass prior was written. priors.md P2 covered Table 20 and the Walter account, not the reference list; batch 19 had already reported from the djvu text that this report cites Walter and ''Dixon'' (the 1957 dissertation), so finding both is not a prediction.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (98, 'accessible-circulation-geometry', NULL, 'EN', 3, 'grey', 'intrinsic', 'FULL-TEXT RETRIEVAL AND READ of candidate 117 (Templer, Mullet, Archea and Margulis, NBS IR 78-1554, An Analysis of the Behavior of Stair Users): nvlpubs.nist.gov/nistpubs/Legacy/IR/nbsir78-1554.pdf, persisted as retrieval-log/<session>/0d39bd2a78b840ff.pdf, then every page''s text layer searched with pymupdf for ramp*, slope*, gradient*, incline* and ratio forms 1:N, and the low-text pages checked.', NULL, 'nist-nvlpubs', 'scoping', 'none', 1, 1, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:51', 'P3a CONFIRMED AND P3b CONFIRMED. HTTP 200, 3.2 MB, 80 pages; the text layer is real (about 93 thousand characters; the twelve low-text pages are stair-inventory plan sheets with riser/tread/width/surface columns, one statistics table, and blank end pages -- the blank one was rendered and looked at). ''ramp'' occurs ten times and every one is incidental: the CPSC scope (''stair, ramp and landing accidents''), ''alternatives to stairs ... (elevators, ramps, etc)'', a stair ''should be clearly seen as a stair and not mistaken for a ramp'', a fall on a stair ''is not like a fall on an even surface like a ramp'', and six citations of a forthcoming Templer book (below). ''slope'' occurs zero times. ''gradient'' occurs eight times and is a FALSE FRIEND: every one is the report''s ''orientation gradient'', a measure of how many visual orientation factors change from step to step, not an inclination. NO RAMP SLOPE OR LENGTH RECOMMENDATION EXISTS IN THE DOCUMENT. Dated ''February 1976, Issued November 1978'' on its title page. ONE FINDING FOR THE FOOTNOTE-c QUESTION, recorded and not resolved: the report repeatedly cites ''Templer, J., Stairs and Ramps, Dowden, Hutchinson and Ross, Stroudsburg, PA., forthcoming'' -- a Templer book on stairs AND ramps announced before REF-01005''s 1979 report. It joins the 1974 dissertation and the FHWA ramp study (REF-01008) as a possible referent of ''Templer, 1977''; none is chosen.', 0, 'Committed in priors.md P3 before any query (be427f35): P3a [KNOWN from the runbook] no rampway recommendation, p=0.9, falsified by any passage recommending a ramp gradient or ramp design value; P3b the text layer is readable by pymupdf, p=0.7.');
INSERT INTO "terms" ("term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES ('TERM-089', 'ramp', 'An inclined walking or wheeling surface that bridges a level difference on a route, considered as an element.', 'circulation', 'Element-level concept: TERM-001 (ramp gradient) is its slope, as TERM-002 (corridor width) is to TERM-048 (circulation route). Subtypes observed in the corpus -- access ramp, curb ramp, step ramp, long ramp, short ramp, hellend vlak, 傾斜路 -- are NARROWER phrases adjudicated to this term, not terms of their own.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "terms" ("term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES ('TERM-090', 'level difference', 'The vertical height to be bridged between two floor or ground levels -- the rise a ramp, step or lift must overcome.', 'circulation', 'Several sources condition a ramp''s permitted gradient on it: Flemish decree Art. 19 bands by niveauverschil (REF-00995), the Australian step-ramp/long-ramp split at a 190 mm rise (REF-00997), REF-01004''s ramp height as an independent variable, REF-01008''s curb heights of 3, 6 and 9 in. Distinct from TERM-022 (level threshold), which is the zero-step doorway entry that removes a level difference.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "terms" ("term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES ('TERM-091', 'ramp run length', 'The horizontal length of a single ramp flight between landings (the UK ''going of a flight'').', 'circulation', 'Sources condition the permitted gradient on it: Approved Document M Table 1 (REF-00992) by going, REF-01002''s 20 ft transit distance, REF-01005 Table 13''s maximum horizontal projection of each run, Walter 1971''s 10 ft and 20 ft ramps as REF-01008 reports them. The mechanism is stated by REF-00996: effort is sustained longer on a longer run. Distinct from level difference, which is the vertical dimension.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "terms" ("term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES ('TERM-092', 'intermediate landing', 'A level platform between successive ramp runs, sized to allow rest, turning or retreat.', 'circulation', 'The Flemish memorandum warrants it in user terms: it lets a wheelchair user turn back without completing the whole ramp (REF-00995). It bounds TERM ramp run length from above.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "terms" ("term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES ('TERM-093', 'ramp usability', 'Whether, and with what effort, difficulty, discomfort or risk, a person can traverse the full length of a ramp -- the outcome a ramp gradient is judged against.', 'circulation', 'Outcome-side concept, as TERM-050 (speech intelligibility) is to TERM-007 (reverberation time). Operationalised in this corpus as completion (REF-01005), perceived effort on the Borg scale (REF-01002), perceived discomfort (REF-01004), difficulty ratings (REF-01008) and physiological load; the Flemish handbook names it fysieke haalbaarheid and makes it the starting point of its rule (REF-00996). Measures are adjudicated to this term as operationalisations, not given terms of their own.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "terms" ("term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES ('TERM-094', 'accessibility audit', 'A structured on-site assessment of a building or facility against an accessibility checklist or standard.', 'methodology', 'A participatory variant (REF-01006) is run by or with disabled people and carries a Co-1 warrant; the method alone does not. An audit measures COMPLIANCE with a yardstick, never what the yardstick should be (REF-01006, REF-01007). Distinct from TERM-060 (post-occupancy evaluation), which assesses a building in use against its intended performance and occupant experience.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-25-resea-REF-01007-MOB', 'REF-01007', 'MOB', 'No people. The unit of study is 38,812 public primary health care facilities (buildings) in Brazil, audited on site in May-October 2012 by researchers from 45 universities hired by the Ministry of Health, using a 22-item yes/no questionnaire (PMAQ-AB first cycle); this paper is a secondary analysis of that census. The items bearing on mobility-impaired users are the entrance sidewalk, floor, access ramp, handrail and wheelchair-accessible door/corridor items.', 38812, 'PROXY', 'PROXY BY R13''s OWN LETTER: no participants. Unlike REF-01006, where every field investigator was a disabled person, nobody disabled took part in this measurement in any role -- the auditors were university researchers, and the authors list the absence of ''complementary qualitative data from people with disabilities'' among the limitations. What the row can support is how often a FEATURE IS PRESENT, never whether a disabled person could use it. And on parameter 3 specifically it supports less than that: the ramp item is binary presence, so a facility scored as having an ''access ramp'' may have one of any gradient.', '2026-09-25 04:34', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'REF-01007', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-25-resea-REF-01008-MOB', 'REF-01008', 'MOB', '120 volunteer subjects tested on 12 outdoor laboratory curb ramps and a mountable curb at Georgia Institute of Technology, August-November 1976, recruited through media and disability and elderly organisations; ''All of the subjects were experienced travellers''. Groups: self-propelled (manual) wheelchair users, powered wheelchair users, cane users, crutch users, people with prosthetic lower limbs, people who walk with difficulty but use no aids, elderly people, able-bodied controls (and visually impaired subjects for the detection tests). Table 2 (rendered page index 28) lists 18 manual wheelchair users -- cerebral palsy, spinal cord injury, polio, paraplegia, spina bifida, multiple birth defects -- whose summary row places all 18 in the 16-25 and 26-35 bands (its subdivision rows put one paraplegic man at 36-45 and one woman with residual polio at 56-65, so the table does not add up; at least 16 of 18 are aged 16-35 on either reading) -- and 6 powered wheelchair users.', 120, 'PARTIAL', 'PARTIAL, AND FOR TWO REASONS THAT CUT DIFFERENTLY. (1) THE TASK IS NARROWER THAN THE PARAMETER: every test ramp is a CURB ramp with a rise of 3, 6 or 9 inches and a run of 2-10 feet. What it measures is how steep a SHORT rise can be, not what gradient a building rampway of any length should have; its own conclusion is that ''steeper ramps are acceptable if they are short''. (2) THE MANUAL WHEELCHAIR GROUP IS YOUNG. At least 16 of Table 2''s 18 manual wheelchair users are aged 16-35 (its summary row says all 18) -- the same objection REF-01005 raised against the 1957 Illinois sample (young, trained users). Elderly people ARE sampled, but as a separate walking group, not as wheelchair users. The authors say the sample ''is somewhat limited so the results must be considered as indicative, rather than conclusive''. Not PROXY: the subjects are disabled people doing the designed task. NOT Co-1: subjects rated ramps they were asked to use; nothing in the report says disabled people shaped the questions, the instrument or the analysis.', '2026-09-25 04:46', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'REF-01008', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (194, 'REF-01007', 1, 'Pinto', 'Alexandro', NULL, NULL, 0, NULL, NULL, 'author', '2026-09-25 04:33', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (195, 'REF-01007', 2, 'Köptcke', 'Luciana Sepúlveda', NULL, NULL, 0, NULL, NULL, 'author', '2026-09-25 04:33', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (196, 'REF-01007', 3, 'David', 'Renata', NULL, NULL, 0, NULL, NULL, 'author', '2026-09-25 04:33', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (197, 'REF-01007', 4, 'Kuper', 'Hannah', NULL, NULL, 0, NULL, NULL, 'author', '2026-09-25 04:33', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "evidence_source_authors" ("id", "ref_id", "position", "last_name", "first_name", "suffix", "orcid", "is_corporate", "corporate_name", "corporate_name_en", "role", "created_at", "created_by_session", "corporate_name_note") VALUES (198, 'REF-01008', 1, 'Templer', 'John A.', NULL, NULL, 0, NULL, NULL, 'author', '2026-09-25 04:46', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (58, 'REF-01007', 'access ramp', 'EN', '2.2 Data Collection, Table 1 (External); Results', 'Does the health facility have access ramp?', 'The instrument''s own name for the feature, recorded as a binary presence item. Harvested verbatim and UNJUDGED (D-0173).', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (59, 'REF-01007', 'accessibility audit', 'EN', '1. Introduction', 'Accessibility audits can be used for monitoring purposes to understand whether facilities are adhering to certain standards', 'The method''s name as this source uses it -- a monitoring instrument against standards. Unjudged.', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (60, 'REF-01007', 'external accessibility', 'EN', 'Abstract; 2.3 Data Processing and Analysis', 'three sub-scales: external accessibility (eight items), internal accessibility (eight items), information accessibility (six items)', 'The source''s sub-scale for the approach, entrance and ramp items. Unjudged.', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (61, 'REF-01008', 'curb ramp', 'EN', 'A Study of Short Ramps, Background (printed p.2) and throughout', 'curb ramps are often so steep that they are not useable by some of the wheelchair users for whom they are intended', 'The report''s own name for the object it tested -- a short ramp through a curb. Unjudged (D-0173).', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (62, 'REF-01008', 'handicapped pedestrians', 'EN', 'title; Technical Report Documentation Page; A Study of Short Ramps', 'how steep should curb ramps be so that they can be used by most handicapped people without too much difficulty?', 'The period''s population term (1974-1980), as the title uses it: ''Provisions for Elderly and Handicapped Pedestrians''. Harvested verbatim, not endorsed; whether it names anything in this project''s identity lens is judgment''s call.', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (63, 'REF-01008', 'short ramps', 'EN', 'Introduction (printed p.1); Part I heading', 'The Laboratory studies were used to develop criteria for the design of short ramps, curb ramps and curb cuts.', 'The length class the recommendations are scoped to -- the source''s own boundary on what Table 20 claims. Unjudged.', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:49', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (126, 93, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Mactaggart et al. (2024) — Adapting and pilot testing a tool to assess the accessibility of primary health facilities for people with disabilities in Luuka District, Uganda (Int J Equity Health)', 'doi:10.1186/s12939-024-02314-0 — PMC11562328, open access; full text persisted this batch as retrieval-log/<session>/18ef7d575e63330c.xml. R9 PRE-CHECKED: DOI not held by any evidence_sources row or staged candidate.', 'RESOLVED', 1, 1, 'NOT ADMITTED THIS BATCH BECAUSE THE ONE NUMBER THAT WOULD PUT IT ON PARAMETER 3 IS IN AN APPENDIX NOT RETRIEVED. The body measures ramp slope and reports failure against a criterion, but the criterion''s value is in Supplementary File Appendix 2 (the full adapted tool). Admitting it with only ''two were too steep'' would file a failure count with no threshold to read it against. tier_guess 1 is a HYPOTHESIS for a Co-1 reading, not a claim: the warrant in the bytes is that eight Ugandan youth researchers with disabilities adapted the instrument over three rounds and co-facilitated the audits; the authors and the analysis are academic (LSHTM / MRC-UVRI). Whether that is co-production in D-0178''s sense or disabled people as trained data collectors is exactly the judgement the next reader must make from the full text, and must not be settled by this guess.', 'WHAT IT SAYS ON RAMPS, VERBATIM FROM THE PERSISTED FULL TEXT: method -- ''For long ramps (over 2 m), 2-3 measurements were taken at various points along the length, and the steepest angle was recorded''; finding -- ''of three facilities with ramps, all reached the minimum required width and had textured, non-slip floors but two were too steep and none had handrails, meaning all failed the overall accessibility criteria for a ramp.'' Five facilities audited, three had ramps. R7: a failure finding. Same cluster as candidates 123/124 (health-facility audits in LMICs) and REF-01006, and the second participatory-audit design found in two batches. NEXT: retrieve Supplementary File Appendix 2 from the publisher (BMC additional files) and read the ramp indicator''s slope criterion.', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:28', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (127, 94, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Campillay-Campillay et al. (2022) — Accessibility in People with Disabilities in Primary Healthcare Centers: A Dimension of the Quality of Care (Int J Environ Res Public Health 19:12439)', 'doi:10.3390/ijerph191912439 — PMC9564706, MDPI gold open access. R9 PRE-CHECKED: not held by any evidence_sources row or staged candidate.', 'RESOLVED', 3, 1, 'SCREENED ON ABSTRACT ONLY. An analytical cross-sectional external audit of 18 primary health care centres in the Atacama region, Chile, with a dichotomous compliance guideline across four dimensions (participation, information, accessibility chain, architectural aspects). The abstract reports architectural-aspect compliance averaging 63.9 percent against a 70 percent lower control limit, but DOES NOT SAY whether a ramp-gradient item is among the architectural indicators or what threshold it used. Not admitted until the body is read for that item.', 'Same document type as candidates 123/124 and REF-01006 -- the title-screen false negative batch 19 named. Adds Chile, a jurisdiction the audit cluster lacks. harm_finding=1: the abstract calls the compliance levels ''a critical situation''.', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:28', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (128, 94, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Obrusnikova et al. (2026) — Statewide Assessment of Public Park Accessibility and Usability and Playground Safety (Int J Environ Res Public Health 23:139)', 'doi:10.3390/ijerph23010139 — PMC12841489, MDPI gold open access. Surfaced by BOTH exec 93 and exec 94; staged once, under the first T2 query that surfaced it. R9 PRE-CHECKED: not held.', 'RESOLVED', 3, 1, 'SCREENED ON ABSTRACT ONLY, AND ITS BEARING ON PARAMETER 3 IS UNPROVEN. A statewide cross-sectional audit of 50 Delaware community parks by trained raters (Community Health Inclusion Index). The abstract says ''Curb-ramp completeness was inconsistent, with detectable warnings frequently absent'' -- that is ramp PRESENCE and warning surfaces, not gradient. Whether curb-ramp or path SLOPE was measured is not established. Staged, not admitted, and a reader should expect it may resolve OUT-OF-SCOPE for this parameter.', 'Recreational-space audits are a second setting beside the health-facility cluster. harm_finding=1 on the abstract''s own inadequacy findings (curb ramps, crossings, transit).', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:28', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (129, 95, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Martins et al. (2016) — Internal structure of Family Health Units: access for people with disabilities (Ciencia e Saude Coletiva 21(10))', 'doi:10.1590/1413-812320152110.20052016 — deposited reference 13 in REF-01007''s Crossref record; SciELO, open access. R9 PRE-CHECKED: not held.', 'RESOLVED', 3, 1, 'SCREENED ON ABSTRACT ONLY. The one audit in this cluster whose abstract reports a MEASURED SLOPE figure: ''of the 90 buildings evaluated, only 47.8% have a wheelchair ramp, of these 30.0% have maximum slope'', against a checklist built on ABNT NBR 9050. The English is a translation and ''have maximum slope'' is ambiguous -- it may mean within the permitted maximum, or at it. Do not extract a compliance rate from that sentence; read the Portuguese body.', 'Found by the REF-01007 backward pass, where the slope-strict title screen scored this reference 0. Portuguese-language full text likely (SciELO); R5 -- a peer-reviewed Brazilian journal article is academic literature, not grey.', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (130, 95, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Mudrick, Breslin, Liang and Yee (2012) — Physical accessibility in primary health care settings: results from California on-site reviews (Disability and Health Journal 5(3))', 'doi:10.1016/j.dhjo.2012.02.002 — deposited reference 7 in REF-01007''s Crossref record. R9 PRE-CHECKED: not held.', 'RESOLVED', 3, 1, 'SCREENED ON ABSTRACT ONLY, AND ITS BEARING ON GRADIENT IS UNPROVEN. 2,389 primary care facilities rated by health-plan reviewers on a 55-item instrument (parking, exterior access, building entrance, interior, exam equipment). The abstract says exterior and building access ''generally met the access criteria'' and puts the barriers in equipment and bathrooms. Whether ramp slope is one of the 55 items, and at what threshold, is exactly what must be read before this is admitted on parameter 3.', 'Scale is the reason to stage it: the largest on-site audit in the health-facility literature reachable from this pass. No author affiliation is in any payload this batch holds, so none is recorded; whether any author''s role carries a Co-1 warrant is a question for the full text, never for memory or venue (D-0178).', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', NULL);
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01007', 'accessible-circulation-geometry', 'RAMP-AUDIT-BR', '2026-09-25 04:33', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:33', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-01008', 'accessible-circulation-geometry', 'RAMP-HIST-02', '2026-09-25 04:46', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:46', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (59, 'REF-01007', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'BR', 'public primary health care facilities (national census, 2012)', 'absent', NULL, NULL, 'Does the health facility have access ramp?', '2.2 Data Collection -- Table 1, Assessment criteria in accessibility audit, External sub-scale', NULL, 'measurement_primary', 'REF-01007', NULL, 'field_observation', 'not_device_scoped', '38,812 facilities observed on site by trained university researchers; no disabled participants.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/2c65a16afca1967b.xml', 'section', NULL, NULL, '2.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Table 1, External sub-scale, sixth item', 'full-read', 'absent-confirmed', NULL, 'ABSENT IS THE FINDING, AND THE SOURCE SAYS WHY IT IS ABSENT. The largest accessibility audit in this corpus -- every public primary care facility in Brazil -- asks whether a ramp EXISTS and never what gradient it has. The authors state the reason in their introduction: ''Many of these tools are complex, requiring measurement of slopes of ramps and widths of doors, and so on. As a consequence, few large-scale accessibility audits have been conducted''. So the omission is a design choice made for scale, and it generalises: an audit can be national OR measure gradient, and this one chose national. RESULT ON THE ITEM (Table 3 and Results text): ''an access ramp (44%)'' and ''a handrail at the entrance (8%)'', better in the richer South/Southeast and in larger municipalities. WHAT THIS ROW MUST NOT BE READ AS: evidence that 44 percent of Brazilian primary care facilities have a USABLE ramp. A binary presence item cannot distinguish a 1:20 ramp from a 1:6 one, and REF-01005 measured that at 1:12 almost half of wheelchair users could not complete the run. It bears on parameter 3 only as a limit on what presence-counts can say. The authors also record that each feature ''was scored as yes or no, yet there may be variation in accessibility''.', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:35', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (60, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'curb ramp; curb height not exceeding 3 in (7.62 cm)', 'numerical', '1:8', 'ratio', 'Table 20 Ramp Gradient Recommendations -- Curb Heights Not Exceeding 3" (7.62 cm): Gradients Steeper Than 1:8 X; 1:8 O; 1:10 O; 1:12 O; 1:16 O (X Not Recommended, O Recommended). *Whenever possible slopes less than the maximum should be employed.', 'A Study of Short Ramps -- Recommendations; Table 20, Ramp Gradient Recommendations', NULL, 'measurement_primary', 'REF-01008', NULL, NULL, 'mixed', 'Table 20 aggregates the ratings of all eight subject groups (Table 19); it is not a wheelchair-only recommendation.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'printed page 34 = zero-based index 53; rendered and read (db21e48738335d82.p0053.png)', 'full-read', 'reviewed', NULL, 'TABLE 20 AS RENDERED: columns are ''Gradients Steeper Than 1:8'', 1:8, 1:10, 1:12, 1:16 under ''Maximum Gradient*''; for curb heights not exceeding 3 in (7.62 cm) the row reads X O O O O (X = Not Recommended, O = Recommended), so the steepest recommended gradient at this height is 1:8. Footnote: ''*Whenever possible slopes less than the maximum should be employed.'' THE RECOMMENDATION IS RISE-CONDITIONED, and that is the finding: the report''s own conclusion is ''steeper ramps are acceptable if they are short''. WHAT WAS AND WAS NOT TESTED AT THIS CELL: the only curb height at which 1:8 is recommended; ramp 9 (1:8, 2 ft, 3 in) was tested and acceptable to manual wheelchair users in ascent (95 percent rating 1 or 2). Acceptability criterion (printed p.14): ''a ramp is considered to be acceptable if about 80% of the subjects rated the ramp as 1 or 2'' on a four-point difficulty scale. Owner ruling 2026-09-18: pre-1990 work is historical grounding, not a current anchor -- T3 grey, cannot lift parameter 3 off proxy. [VERBATIM-EXEMPT: TABLE CELLS, NOT A SENTENCE. The only text layer that can be checked (the Internet Archive DjVuTXT, 639e73bd17c02f7f.txt, around the line reading Table 20 Ramp Gradient Recommendations) serialises the table COLUMN BY COLUMN and reads every O mark as the digit 0, so no row of Table 20 exists as a contiguous string in any artefact. This claim_text is the row transcribed from the RENDERED page (db21e48738335d82.p0053.png, printed page 34, zero-based index 53), and the column-wise text layer agrees with it cell for cell. The sentence introducing the table verifies verbatim: Based on these findings, Table 20 shows recommendations for maximum acceptable gradients for three different curb heights.] || 2026-09-25 extraction_status SET verified -> reviewed (Written as ''verified'' minutes earlier in the same batch; corrected before emission. This row''s claim_text is a TRANSCRIPTION of table cells read off a rendered page and carries a VERBATIM-EXEMPT warrant, so nothing byte-checks it. The corpus''s other exempt transcriptions (REF-01005, extractions 52-57) are ''reviewed'', and ''verified'' is kept here for rows whose claim_text verifies byte-for-byte against a persisted artefact (63, 64).)', '2026-09-25 04:47', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (61, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'curb ramp; curb height not exceeding 6 in (15.2 cm)', 'numerical', '1:10', 'ratio', 'Table 20 Ramp Gradient Recommendations -- Curb Heights Not Exceeding 6" (15.2 cm): Gradients Steeper Than 1:8 X; 1:8 X; 1:10 O; 1:12 O; 1:16 O (X Not Recommended, O Recommended). *Whenever possible slopes less than the maximum should be employed.', 'A Study of Short Ramps -- Recommendations; Table 20, Ramp Gradient Recommendations', NULL, 'measurement_primary', 'REF-01008', NULL, NULL, 'mixed', 'Table 20 aggregates the ratings of all eight subject groups (Table 19); it is not a wheelchair-only recommendation.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'printed page 34 = zero-based index 53; rendered and read (db21e48738335d82.p0053.png)', 'full-read', 'reviewed', NULL, 'TABLE 20 AS RENDERED: columns are ''Gradients Steeper Than 1:8'', 1:8, 1:10, 1:12, 1:16 under ''Maximum Gradient*''; for curb heights not exceeding 6 in (15.2 cm) the row reads X X O O O (X = Not Recommended, O = Recommended), so the steepest recommended gradient at this height is 1:10. Footnote: ''*Whenever possible slopes less than the maximum should be employed.'' THE RECOMMENDATION IS RISE-CONDITIONED, and that is the finding: the report''s own conclusion is ''steeper ramps are acceptable if they are short''. WHAT WAS AND WAS NOT TESTED AT THIS CELL: NO RAMP OF 1:10 OVER A 6-INCH CURB WAS TESTED (Table 1): the 6-inch ramps were 1:8 (ramp 3, unacceptable), 1:12 (ramps 2 and 4) and 1:16 and 1:20. The 1:10 cell is the authors'' interpolation between a tested failure and a tested success. Acceptability criterion (printed p.14): ''a ramp is considered to be acceptable if about 80% of the subjects rated the ramp as 1 or 2'' on a four-point difficulty scale. Owner ruling 2026-09-18: pre-1990 work is historical grounding, not a current anchor -- T3 grey, cannot lift parameter 3 off proxy. [VERBATIM-EXEMPT: TABLE CELLS, NOT A SENTENCE. The only text layer that can be checked (the Internet Archive DjVuTXT, 639e73bd17c02f7f.txt, around the line reading Table 20 Ramp Gradient Recommendations) serialises the table COLUMN BY COLUMN and reads every O mark as the digit 0, so no row of Table 20 exists as a contiguous string in any artefact. This claim_text is the row transcribed from the RENDERED page (db21e48738335d82.p0053.png, printed page 34, zero-based index 53), and the column-wise text layer agrees with it cell for cell. The sentence introducing the table verifies verbatim: Based on these findings, Table 20 shows recommendations for maximum acceptable gradients for three different curb heights.] || 2026-09-25 extraction_status SET verified -> reviewed (Written as ''verified'' minutes earlier in the same batch; corrected before emission. This row''s claim_text is a TRANSCRIPTION of table cells read off a rendered page and carries a VERBATIM-EXEMPT warrant, so nothing byte-checks it. The corpus''s other exempt transcriptions (REF-01005, extractions 52-57) are ''reviewed'', and ''verified'' is kept here for rows whose claim_text verifies byte-for-byte against a persisted artefact (63, 64).)', '2026-09-25 04:47', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (62, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'curb ramp; curb height not exceeding 9 in (22.9 cm)', 'numerical', '1:12', 'ratio', 'Table 20 Ramp Gradient Recommendations -- Curb Heights Not Exceeding 9" (22.9 cm): Gradients Steeper Than 1:8 X; 1:8 X; 1:10 X; 1:12 O; 1:16 O (X Not Recommended, O Recommended). *Whenever possible slopes less than the maximum should be employed.', 'A Study of Short Ramps -- Recommendations; Table 20, Ramp Gradient Recommendations', NULL, 'measurement_primary', 'REF-01008', NULL, NULL, 'mixed', 'Table 20 aggregates the ratings of all eight subject groups (Table 19); it is not a wheelchair-only recommendation.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'printed page 34 = zero-based index 53; rendered and read (db21e48738335d82.p0053.png)', 'full-read', 'reviewed', NULL, 'TABLE 20 AS RENDERED: columns are ''Gradients Steeper Than 1:8'', 1:8, 1:10, 1:12, 1:16 under ''Maximum Gradient*''; for curb heights not exceeding 9 in (22.9 cm) the row reads X X X O O (X = Not Recommended, O = Recommended), so the steepest recommended gradient at this height is 1:12. Footnote: ''*Whenever possible slopes less than the maximum should be employed.'' THE RECOMMENDATION IS RISE-CONDITIONED, and that is the finding: the report''s own conclusion is ''steeper ramps are acceptable if they are short''. WHAT WAS AND WAS NOT TESTED AT THIS CELL: NO RAMP OF 1:12 OVER A 9-INCH CURB WAS TESTED (Table 1): the 9-inch ramps were 1:5.3, 1:8, 1:10.67 and 1:13.3, and only 1:13.3 (ramp 5) was acceptable to manual wheelchair users in ascent (84 percent). The 1:12 cell is an interpolation just steeper than the gentlest tested 9-inch ramp. Acceptability criterion (printed p.14): ''a ramp is considered to be acceptable if about 80% of the subjects rated the ramp as 1 or 2'' on a four-point difficulty scale. Owner ruling 2026-09-18: pre-1990 work is historical grounding, not a current anchor -- T3 grey, cannot lift parameter 3 off proxy. [VERBATIM-EXEMPT: TABLE CELLS, NOT A SENTENCE. The only text layer that can be checked (the Internet Archive DjVuTXT, 639e73bd17c02f7f.txt, around the line reading Table 20 Ramp Gradient Recommendations) serialises the table COLUMN BY COLUMN and reads every O mark as the digit 0, so no row of Table 20 exists as a contiguous string in any artefact. This claim_text is the row transcribed from the RENDERED page (db21e48738335d82.p0053.png, printed page 34, zero-based index 53), and the column-wise text layer agrees with it cell for cell. The sentence introducing the table verifies verbatim: Based on these findings, Table 20 shows recommendations for maximum acceptable gradients for three different curb heights.] || 2026-09-25 extraction_status SET verified -> reviewed (Written as ''verified'' minutes earlier in the same batch; corrected before emission. This row''s claim_text is a TRANSCRIPTION of table cells read off a rendered page and carries a VERBATIM-EXEMPT warrant, so nothing byte-checks it. The corpus''s other exempt transcriptions (REF-01005, extractions 52-57) are ''reviewed'', and ''verified'' is kept here for rows whose claim_text verifies byte-for-byte against a persisted artefact (63, 64).)', '2026-09-25 04:47', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (63, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'curb ramps, rises 3-9 in, runs 2-10 ft', 'qualitative', 'a steeper gradient is acceptable over a shorter rise and run', NULL, 'Secondly, it is clear that steeper ramps are acceptable if they are short.', 'A Study of Short Ramps -- Conclusions (after Table 19)', NULL, 'measurement_primary', 'REF-01008', NULL, NULL, 'mixed', NULL, NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '33', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'printed page 33 = zero-based index 52, rendered (db21e48738335d82.p0052.png)', 'full-read', 'verified', NULL, 'The conclusion Table 20 is built on, and the fourth independent statement of length-conditioning on parameter 3 in this corpus: REF-01002''s 7 percent up to 20 ft, REF-01003''s short-distance acceptability, REF-00996''s mechanism (the greater the rise, the gentler the ramp, because the effort is sustained longer), and this. It is what a single maximum gradient without a length or rise cannot express, and it is why the 1:12 rows in this corpus do not contradict each other.', '2026-09-25 04:47', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:47', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (64, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'UK', '20 ft (6.1 m) indoor laboratory ramp; self-propelled wheelchairs (Walter 1971, reported at second hand)', 'numerical', '1:16', 'ratio', 'Gradients that were rated by a high percentage of the subjects to be ''easy'' or ''comfortable'' were recommended—for self-propelled wheelchairs, a slope of 1:9 for the 10 foot (3.05 m) ramp, and 1:16 for the 20 foot (6.1 m) ramp', 'A Study of Short Ramps -- Previous Studies (Walter, reference 3)', NULL, 'untraced', NULL, NULL, NULL, 'manual_self_propelled', 'Walter''s subjects are not described in this account beyond ''self-propelled'' and ''assistant-propelled'' wheelchairs.', 'Reported SECOND-HAND by REF-01008. root_ref_id is deliberately NULL: Walter 1971 is search_candidates 109, not an admitted source, so there is no row to point at, and external_root_registry has no writer in db.py. This is NOT a claim that REF-01008 measured 1:16 over 20 ft -- its longest test ramp is 10 ft. Same treatment as extraction 57 (Elmer 1957 via REF-01005).', 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/639e73bd17c02f7f.txt', 'page', NULL, NULL, '4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'printed page 4 = zero-based index 23, rendered (db21e48738335d82.p0023.png)', 'full-read', 'verified', NULL, 'WALTER''S RAMP AT SECOND HAND, FROM A SECOND INDEPENDENT READER. As printed: an adjustable indoor laboratory ramp, 20 ft at 1:8.6 to 1:16 and 10 ft at 1:5.5 to 1:10, rated on a four-point scale (easy, comfortable, difficult, impossible); recommended for SELF-PROPELLED wheelchairs 1:9 over 10 ft and 1:16 over 20 ft; for ASSISTANT-PROPELLED 1:9 over 10 ft and 1:12 over 20 ft. The page prints ''10 foot (6.1 m)'' in the assistant-propelled clause -- a unit slip in the source (10 ft is 3.05 m), recorded as printed. WHAT IT CORROBORATES: REF-01005 (extraction 54) reports that Walter and Steinfeld both found 1:16 over 20 ft accessible. Templer, writing independently, gives the same 1:16-over-20-ft figure for Walter. That corroborates the REPORT OF Walter by a second reader; it does NOT make Walter a second root, and v_value_independence must still count Walter once, and only when Walter itself is read. GAP-026 and the 2026-09-25 owner ruling: Walter itself is exhausted, so this second-hand account is the best text of Walter this project will hold for now.', '2026-09-25 04:47', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:47', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (65, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'curb ramp 4: 1:12, 6 ft (1.83 m) long, over a 6 in (15.24 cm) curb; ascent', 'numerical', '1:12', 'ratio', 'Table 3 Gradient Ratings by Manual Wheelchair Users: Ascent -- gradient 1:12, curb height 6" (15.2 cm), ramp 4, 6'' lgth 1.83m: subject rating 1.26, 100% of subjects rating a 1 or 2, tester rating (1.84). Ratings: 1 Not at all difficult, 2 A little difficult, 3 Difficult, 4 Very difficult.', 'A Study of Short Ramps -- Results, 1a Manual Wheelchair Users; Table 3, Gradient Ratings by Manual Wheelchair Users: Ascent', NULL, 'measurement_primary', 'REF-01008', NULL, NULL, 'manual_self_propelled', 'Manual (self-propelled) wheelchair users; Table 2 lists 18, at least 16 of them aged 16-35.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Table 3 at printed page 17 = zero-based index 36, rendered; prose verdict at printed page 14 = index 33', 'full-read', 'reviewed', NULL, 'READ OFF THE RENDERED TABLE 3. ''inferred'' on the edge because the prose names ramps by NUMBER only; that ramp 4 is 1:12 over 6 in for 6 ft comes from joining Table 1. THE CONTRAST WITH REF-01005 IS THE POINT AND IT IS NOT A CONTRADICTION: REF-01005 found almost half of wheelchair users could not complete a 1:12 RUN over its test length, while here every manual wheelchair user rated 1:12 acceptable over a 6-inch RISE and a 6-foot run. Same gradient, different length -- the rise- and length-conditioning that REF-01002 (20 ft bound), REF-01003 (short distances) and this report''s own conclusion (''steeper ramps are acceptable if they are short'') all state. A 1:12 value without its rise or run is not the same claim. The tester''s ratings run harder than the subjects'' own at almost every ramp (1.84 against 1.26 here). [VERBATIM-EXEMPT: TABLE CELL, NOT A SENTENCE. Table 3 is a grid of cells (ramp number, length, subject mean, percent rating 1 or 2, tester mean in parentheses); the Internet Archive DjVuTXT (639e73bd17c02f7f.txt, from the line reading Table 3 Gradient Ratings by Manual Wheelchair Users: Ascent) carries only fragments of it, out of order. This claim_text is the cell transcribed from the RENDERED page (db21e48738335d82.p0036.png, printed page 17, zero-based index 36), with the gradient and curb height from the column and row headers and the ramp geometry from Table 1 (db21e48738335d82.p0024.png). The acceptability verdict verifies verbatim in the prose on printed page 14: From Table 3, the curb ramps to the right of the heavy line are acceptable for ascent: Ramps #1, 4, 5, 9, 10, 11, 12 and 13 are acceptable Ramps #2, 3, 6, 7, 8 are unacceptable] || 2026-09-25 extraction_status SET verified -> reviewed (Written as ''verified'' minutes earlier in the same batch; corrected before emission. This row''s claim_text is a TRANSCRIPTION of table cells read off a rendered page and carries a VERBATIM-EXEMPT warrant, so nothing byte-checks it. The corpus''s other exempt transcriptions (REF-01005, extractions 52-57) are ''reviewed'', and ''verified'' is kept here for rows whose claim_text verifies byte-for-byte against a persisted artefact (63, 64).)', '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'finding', '=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (66, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'curb ramp 6: 1:10.67, 8 ft (2.44 m) long, over a 9 in (22.85 cm) curb; ascent', 'numerical', '1:10.67', 'ratio', 'Table 3 Gradient Ratings by Manual Wheelchair Users: Ascent -- gradient 1:10.67, curb height 9" (22.9 cm), ramp 6, 8'' lgth 2.44m: subject rating 2.16, 58% of subjects rating a 1 or 2, tester rating (2.42). Only ramps to the right of the heavy line are considered acceptable; ramp 6 lies to its left.', 'A Study of Short Ramps -- Results, 1a Manual Wheelchair Users; Table 3, Gradient Ratings by Manual Wheelchair Users: Ascent', NULL, 'measurement_primary', 'REF-01008', NULL, NULL, 'manual_self_propelled', 'Manual (self-propelled) wheelchair users; Table 2 lists 18, at least 16 of them aged 16-35.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Table 3 at printed page 17 = zero-based index 36, rendered; Table 1 at printed page 5 = index 24, rendered', 'full-read', 'reviewed', NULL, 'READ OFF THE RENDERED TABLE 3: ramp 6 (1:10.67, 8 ft, 9 in) -- subject mean 2.16, only 58 percent rating it 1 or 2, tester mean 2.42 -- below the report''s ~80 percent acceptability line. Also unacceptable in ascent: ramp 3 (1:8, 4 ft, 6 in) 44 percent; ramp 8 (1:8, 6 ft, 9 in) 47 percent; ramp 7 (1:5.3, 4 ft, 9 in) 32 percent with two subjects unable. WHY THIS ROW EXISTS: THE GEOMETRY OF RAMP 6 IS THE GEOMETRY OF REF-01005 TABLE 13''s 1:10 ROW. Table 13 (rendered this batch, 5dd866a236fb5978.p0056.png) allows ''If slope = 10.0% (1:10) or less steep'' with a maximum run of 8 ft and a maximum rise of 9 in -- and 9 in over 8 ft is 1:10.67, ramp 6 exactly. Its 1:8 row (2 ft run, 3 in rise) is likewise ramp 9 exactly. Both rows carry footnote c, ''Based on research of others (Templer, 1977 and Walters, 1971)''. So the combination Table 13 permits in its 1:10 band is one this report TESTED AND FOUND UNACCEPTABLE to manual wheelchair users in ascent, and this report''s own Table 20 does not recommend 1:10 above a 6-inch curb. HELD AS AN OBSERVATION, NOT AN IDENTIFICATION: the two matching geometries are consistent with footnote c''s Templer being this project''s ramp work (tested August-November 1976; an interim report could carry 1977), but THIS REPORT IS DATED MAY 1980 and the referent is not identified -- candidate 115 stays PENDING. Walter''s 10-ft recommendation as this report gives it (printed p.4: 1:9, self-propelled) is steeper than 1:10, so Table 13''s 1:10 band sits between its two named warrants rather than being taken from either. [VERBATIM-EXEMPT: TABLE CELL, NOT A SENTENCE. Table 3 is a grid of cells (ramp number, length, subject mean, percent rating 1 or 2, tester mean in parentheses); the Internet Archive DjVuTXT (639e73bd17c02f7f.txt, from the line reading Table 3 Gradient Ratings by Manual Wheelchair Users: Ascent) carries only fragments of it, out of order. This claim_text is the cell transcribed from the RENDERED page (db21e48738335d82.p0036.png, printed page 17, zero-based index 36), with the gradient and curb height from the column and row headers and the ramp geometry from Table 1 (db21e48738335d82.p0024.png). The acceptability verdict verifies verbatim in the prose on printed page 14: From Table 3, the curb ramps to the right of the heavy line are acceptable for ascent: Ramps #1, 4, 5, 9, 10, 11, 12 and 13 are acceptable Ramps #2, 3, 6, 7, 8 are unacceptable] || 2026-09-25 extraction_status SET verified -> reviewed (Written as ''verified'' minutes earlier in the same batch; corrected before emission. This row''s claim_text is a TRANSCRIPTION of table cells read off a rendered page and carries a VERBATIM-EXEMPT warrant, so nothing byte-checks it. The corpus''s other exempt transcriptions (REF-01005, extractions 52-57) are ''reviewed'', and ''verified'' is kept here for rows whose claim_text verifies byte-for-byte against a persisted artefact (63, 64).)', '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'finding', '=');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (1, 58, 'NAMES-NEW', 'TERM-089', 'NAMES-NEW. The vocabulary holds the ramp''s SLOPE (TERM-001) but not the RAMP: eight observations across six sources name the element itself -- a feature that is present or absent (REF-01007''s audit item ''Does the health facility have access ramp?''), a class with its own gradient band (step ramp / long ramp, REF-00997), a length class (short ramps, REF-01008), a statutory object (傾斜路, REF-00990). Precedent: TERM-048 circulation route is held beside TERM-002 corridor width. Without an element term every one of those phrases has to be forced onto the gradient or left unlinked. Minted from this observation because its source uses the bare element in English as an audit item.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (2, 18, 'NAMES-NEW', 'TERM-090', 'NAMES-NEW. ''niveauverschillen'' is the variable the Flemish decree conditions its gradient bands on (''tien procent bij niveauverschillen tot 10 cm''), and the same variable carries the permitted gradient in at least three other sources in this corpus under other names (rise, height, curb height). No term holds it, so a gradient stated ''for a rise of X'' has nothing to point at for X. The English canonical is a literal gloss of niveauverschil, not a back-translated alias: the alias belongs to this Dutch observation, in its own language.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (3, 13, 'NAMES-NEW', 'TERM-091', 'NAMES-NEW. ''going of a flight'' is the variable Approved Document M sets its gradient limits against (''Limits for ramp gradients / Going of a flight / Maximum gradient / Maximum rise''), and run length is the single most repeated conditioning variable in this parameter''s evidence -- which is why three 1:12s in three jurisdictions are not one figure (the observation''s own note). No term holds it. Canonical in plain English rather than the UK term, with ''going'' kept as the observed phrase.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (4, 19, 'NAMES-NEW', 'TERM-092', 'NAMES-NEW. ''tussenbordes'' names a design element the vocabulary lacks: the decree requires one of 120 x 150 cm above a 50 cm level difference or a 10 m ramp over 4 percent, and its warrant is the most user-centred rationale any code in this corpus states. It is not TERM-048 (a route) nor the ramp itself. The English canonical is a literal gloss (tussen = between, bordes = landing).', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (5, 43, 'NAMES-NEW', 'TERM-093', 'NAMES-NEW. REF-00980 asks about ''the usability of the range of ramp slopes allowed under the current ADA accessibility guidelines'' -- the property every study on this parameter measures and no term names. Without it the vocabulary has an input (TERM-001) and no outcome, so an effort scale, a completion rate and a feasibility criterion cannot be recognised as measuring the same thing. English canonical from an English T1 title word, not coined.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (6, 59, 'NAMES-NEW', 'TERM-094', 'NAMES-NEW. This batch''s entire cluster is accessibility audits (REF-01006, REF-01007, candidates 123, 126-130), and the corpus has no term for the method -- so the one thing every one of them shares cannot be retrieved as a concept. REF-01007 uses the phrase for exactly this: ''Accessibility audits can be used for monitoring purposes to understand whether facilities are adhering to certain standards''. It is not POE (TERM-060).', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (7, 1, 'NAMES-EXISTING', 'TERM-001', '''ramp slope'' in ''greater power and pushrim force on steeper ramp slopes'' is the slope of a ramp, which is TERM-001''s definition word for word. The setting is a transit bus boarding ramp, recorded on the source''s extractions; the concept is the same.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (8, 2, 'DEFERRED', NULL, '''ascending slopes'' is a skill item in a wheelchair skills test (''negotiating kerbs, ascending slopes, traversing tracks''): it names an ACTIVITY (a wheelchair task on a slope), not a design parameter or element. CLAUDE.md section 6 sends activities to the ICF lens (base_icf d4 mobility codes), and the vocabulary''s only activity-shaped terms are the functional-axis rows TERM-031..047, a coinage the owner ruled bad on 2026-08-18. Whether task phrases get term rows or ICF links is undecided; forcing either here would decide it by accident.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (9, 3, 'DEFERRED', NULL, '''slope propulsions'' names propelling a wheelchair on slopes as the unit of exposure for musculoskeletal risk: it names an ACTIVITY (a wheelchair task on a slope), not a design parameter or element. CLAUDE.md section 6 sends activities to the ICF lens (base_icf d4 mobility codes), and the vocabulary''s only activity-shaped terms are the functional-axis rows TERM-031..047, a coinage the owner ruled bad on 2026-08-18. Whether task phrases get term rows or ICF links is undecided; forcing either here would decide it by accident.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (10, 4, 'NAMES-EXISTING', 'TERM-001', '''inclines'' in ''propulsion at different speeds and inclines, ascending and descending ramps'' is the inclination of the ramps being ascended -- the ramp''s slope. TERM-001.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (11, 5, 'NAMES-EXISTING', 'TERM-001', '''running slope'' in ''Ramp runs shall have a running slope not steeper than 1:12'' (ADA 405.2) is the slope of a ramp run in the direction of travel. TERM-001; ''running'' distinguishes it from cross slope, which is not this parameter.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (12, 6, 'DEFERRED', NULL, '自走 (''self-propelling'', in ''depending on the gradient you may not be able to go by self-propulsion'') names the propulsion mode, which the schema holds as source_value_extractions.device_class = ''manual_self_propelled'': the concept IS held, but as a column vocabulary rather than a term (rule 5: one home). Minting a term for it would create a second home; adjudicating NOT-OURS would say it is not a concept of ours, which is false. Deferred until the term-versus-column placement is decided for held vocabularies.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (13, 7, 'NAMES-EXISTING', 'TERM-001', '勾配 is defined by the source itself -- 勾配とは、斜面の程度のことをいいます, ''gradient means the degree of a slope'' -- under the heading on the legal スロープの勾配基準 (ramp gradient standard, 1/12). It names the slope of a ramp. TERM-001.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (14, 8, 'NAMES-EXISTING', 'TERM-001', '''Neigung'' in ''Rampenläufe dürfen maximal eine Neigung von 6 % aufweisen'' is the inclination of a ramp run. TERM-001, stated as a percentage.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (15, 9, 'NAMES-EXISTING', 'TERM-089', '傾斜路 is the Japanese statutory term for a ramp as an element (''傾斜路 ... used by unspecified and many persons or mainly by the elderly and disabled''). It names the ramp, not its slope, so it points at the element term minted this batch rather than TERM-001.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (16, 10, 'DEFERRED', NULL, '移動等円滑化経路 names a legally DESIGNATED accessible route, the route the 1:12 ceiling attaches to (the observation''s own note). TERM-048 (circulation route) is the nearest and is broader and defined as horizontal movement through a building, which this route is not. An ''accessible route'' term is probably warranted, but minting its English name from a Japanese statute would be back-translation (R11); it should be minted from an English-language source that uses the phrase itself.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (17, 11, 'DEFERRED', NULL, '敷地内の通路 (''path within the site'') names an external site path that carries its own ramp provisions. TERM-048 is scoped to routes THROUGH A BUILDING, so it does not fit, and the vocabulary has no site-route term. Whether site and building routes are one concept or two is a scoping decision for the circulation vocabulary, not one this phrase can settle.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (18, 12, 'NOT-OURS', NULL, '誘導すべき建築物特定施設 names Japan''s GUIDED (誘導) standard, which buildings are steered toward rather than held to. The distinction it draws -- guidance versus mandatory -- is carried in this project by the tier ladder (T5 national_fw versus T6 code), not by the concept vocabulary; TERM-075 is defined as BINDING requirements, so it would be wrong here. Not a term concept; the observation''s substance is already represented by how the source is tiered.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (19, 14, 'NAMES-EXISTING', 'TERM-075', '義務基準 (''mandatory standard'') is binding accessibility requirements, TERM-075''s definition. The DPO uses it pejoratively -- the mandatory standard alone does not make smooth use possible -- which is exactly TERM-075''s scope note: the regulatory floor is not evidence of adequacy.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (20, 15, 'NOT-OURS', NULL, '''min. grade best practice'' is a SPEECH ACT the IPC performs on its 1:20 figure (best practice rather than maximum). ''Best practice'' is a determination-level category in this project (tier-system section 8, ''best practice as currently known''), carried by extraction figure_role and comparator, not a concept the vocabulary names. Recording it as a term would put a determination label in the vocabulary.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (21, 16, 'NOT-OURS', NULL, '''secondary or ancillary facilities'' is the IPC''s facility-importance scope for its relaxed 1:14 figure. It is a condition on one guide''s figure, held in that extraction''s setting, not a concept the vocabulary needs; minting a facility-importance classification on a single guide''s wording would be thin warrant.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (22, 17, 'NAMES-EXISTING', 'TERM-001', '''hellingspercentage'' is the gradient of a helling (ramp) expressed as a percentage (''Het hellingspercentage bedraagt hoogstens ...''). TERM-001; the observation''s point about ratio-versus-percentage notation is a unit fact the extractions carry in claimed_unit, not a second concept.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (23, 20, 'NAMES-EXISTING', 'TERM-093', '''fysieke haalbaarheid'' (''physical feasibility'' of the independent wheelchair user) is the Flemish handbook''s name for whether a user can manage the whole ramp -- the outcome the gradient is judged against, which the handbook makes the starting point of its rule. That is the ramp usability term minted this batch, whose scope note names this phrase.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (24, 21, 'NAMES-EXISTING', 'TERM-016', '''zelfstandige rolstoelgebruiker'' is a wheelchair user, TERM-016, narrowed by the source''s own parenthesis to the INDEPENDENT (self-propelling) user as the design case. The narrowing is real and is carried on extractions as device_class manual_self_propelled; the concept named is TERM-016.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (25, 22, 'NOT-OURS', NULL, '''uitgangspunt'' (''starting point'') is a discourse word marking the speech act -- feasibility is what the rule is derived FROM. The substance is carried by observation 20''s adjudication to ramp usability; the word itself names no concept.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (26, 23, 'NAMES-EXISTING', 'TERM-089', '''hellend vlak'' is, in the source''s own words, what a SHORT helling is often called (''Een korte helling wordt vaak hellend vlak genoemd'') -- a short ramp permitted a steeper percentage. A narrower phrase for the ramp element, adjudicated to it; its length condition is what ramp run length holds.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (27, 24, 'NAMES-EXISTING', 'TERM-089', '''step ramp'' is a ramp class defined by rise (<190 mm) and given its own gradient band (1:8). It names the element, narrowed by level difference; adjudicated to the ramp element term rather than minted separately, per that term''s scope note.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (28, 25, 'NAMES-EXISTING', 'TERM-089', '''long ramp'' is the complement of ''step ramp'' (rise >190 mm, 1:14). Same element, same adjudication; the rise that divides the two classes is level difference.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (29, 26, 'NOT-OURS', NULL, '''prescriber'' names a clinical ROLE -- the actor the document assigns the gradient decision to, with authority to depart from AS 1428.1 on documented reasoning. Not a built-environment concept. What it raises for Co-2 (clinical authority over a design parameter) is recorded in the observation''s notes and belongs in a Co-2 reading, not the vocabulary.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (30, 27, 'NOT-OURS', NULL, '''Class 1 and 2 buildings'' is the Australian National Construction Code''s building classification. It decides whether AS 1428.1 applies, which is load-bearing for the question, but it is a jurisdiction''s legal category, not a concept of ours; its effect is recorded where the source''s applicability claim is extracted.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (31, 28, 'DEFERRED', NULL, '''Livable Housing Design Standard'' is a named instrument. Named instruments are narrower aliases of a concept (TERM-064''s scope note), but which concept depends on the level applied: a minimum dwelling-access level is TERM-059 (visitability), a full-use level is TERM-068 (accessible housing). The observed context (''Livable Housing Guidelines are advisory'') does not say which level, so it cannot be adjudicated on this source.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (32, 29, 'DEFERRED', NULL, '''private dwellings'' names a SETTING. The vocabulary holds housing only as standards of a dwelling (TERM-059 visitability, TERM-068 accessible housing), not the dwelling as a setting; TERM-070 (school learning environment) shows setting terms exist, so a dwelling setting term is a reasonable mint -- but one FAQ answer is thin warrant, and the housing slug is where it should be decided.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (33, 30, 'NOT-OURS', NULL, '''disabled-by-design'' is a title-level framing claim about causation (design disables users of mobility devices). It is a thesis the review argues, not a design concept the vocabulary names; its substance is the review''s findings, which are extracted.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (34, 31, 'NOT-OURS', NULL, '''factor of disablement'' is the same causal framing as observation 30, stated in the conclusions. Not a vocabulary concept, for the same reason.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (35, 32, 'NAMES-EXISTING', 'TERM-079', '''mobility assistive devices'' (the review''s MobAD) are devices supporting locomotion, TERM-079 (mobility aid). TERM-079''s scope note keeps the device distinct from the person (TERM-016), and the phrase names the device.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (36, 33, 'NOT-OURS', NULL, '''least accessible elements'' is a ranking phrase (''were deemed to be the least accessible elements''), not a concept. The elements it ranks (pathways, boarding ramps, entrances) are named separately.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (37, 34, 'DEFERRED', NULL, '''ramp incident'' names an ADVERSE EVENT on a ramp (78 percent of wheelchair users had one in three years). The corpus records harm as harm_finding flags and case studies and has no adverse-event vocabulary; whether event types (ramp incident, fall, tip-over) warrant terms is a vocabulary question the stair slug will raise too (candidate 117, rehomed this batch, is a stair-accident study). Deferred rather than decided on one source.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (38, 35, 'NAMES-EXISTING', 'TERM-001', '''steep ramp slope'' is TERM-001 with an evaluative qualifier: over 60 percent of those with an incident named steep ramp slope as the contributing factor. The concept is the slope; ''steep'' is the source''s judgment of it.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (39, 36, 'DEFERRED', NULL, '''exterior ramp thresholds'' names the transition where a (bus) ramp meets the ground or kerb -- a lip or level change at the ramp''s end. TERM-022 (level threshold) is a zero-step DOORWAY entry, a different place and function. REF-01008''s lip findings (a 1 in lip made an acceptable ramp unacceptable) bear on the same concept. It likely warrants a term, but this abstract fragment (''Steep ramp slope, exterior ramp thresholds and'') does not define it; mint from a source that does.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (40, 37, 'NOT-OURS', NULL, '''coping mechanisms'' names users'' STRATEGIES for propelling up a ramp -- a behavioural finding about people, not a design concept. Its content belongs in the source''s qualitative findings.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (41, 38, 'NOT-OURS', NULL, '''solutions'' is a generic word the source puts in scare quotes (''proposed solutions to accessibility, such as ramps, often generate problems of their own''). It names nothing; the claim it carries is a finding, and ramps as an element are the ramp term.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (42, 39, 'NOT-OURS', NULL, '''tipping point'' names a THRESHOLD VALUE on the gradient scale (5.50 percent, after which all respondents felt uncertainty). A threshold is the output of a determination, not a vocabulary concept, and a term that named one would be the value-bearing container add-term refuses. The underlying outcome (uncertainty) is ramp usability; the phrase itself is a value.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (43, 40, 'DEFERRED', NULL, '''critical longitudinal slopes'' are threshold slopes on forest and park TRAILS: the ramp-versus-route boundary is unresolved in this corpus: TERM-001 is defined as the slope of a RAMP, this source measures the running slope of outdoor PATHS or trails, and no term holds route gradient. Extraction 49 already files REF-01003''s path slopes on parameter 3 (ramp gradient), so the same conflation is live in the evidence. Adjudicating this phrase onto TERM-001 would ratify it; minting a route-gradient term would imply extraction 49 is mis-filed. That is a judgment about the parameter''s scope, not about this phrase, and it is left for the batch that re-determines parameter 3.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (44, 41, 'DEFERRED', NULL, '''complex independent movement with certain risk'' is a graded usability category, which would otherwise go to ramp usability -- but it grades movement on TRAILS: the ramp-versus-route boundary is unresolved in this corpus: TERM-001 is defined as the slope of a RAMP, this source measures the running slope of outdoor PATHS or trails, and no term holds route gradient. Extraction 49 already files REF-01003''s path slopes on parameter 3 (ramp gradient), so the same conflation is live in the evidence. Adjudicating this phrase onto TERM-001 would ratify it; minting a route-gradient term would imply extraction 49 is mis-filed. That is a judgment about the parameter''s scope, not about this phrase, and it is left for the batch that re-determines parameter 3.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (45, 42, 'NAMES-EXISTING', 'TERM-001', '''ramp slope'' in ''the usability of the range of ramp slopes allowed under the current ADA accessibility guidelines'' is TERM-001 exactly.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (46, 44, 'NAMES-EXISTING', 'TERM-001', '''ramps of different slopes'' names the independent variable of a kinematic study -- the ramp''s slope. TERM-001.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (47, 45, 'NAMES-EXISTING', 'TERM-001', '''running slope'' in ''requirements for ramp design, including their maximum running slope and cross slope'' is the slope of a RAMP along the direction of travel. TERM-001; cross slope is a different parameter.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (48, 46, 'NAMES-EXISTING', 'TERM-093', '''perceived effort'' (Borg scale) is the measure REF-01002 uses for how hard wheelchair users find it to negotiate ramps. It operationalises ramp usability, and the term''s scope note records Borg-scale perceived effort as one of its measures; measures are adjudicated to the outcome they measure rather than given terms of their own.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (49, 47, 'DEFERRED', NULL, '''running slope'' here is the running slope of OUTDOOR PATHWAYS (''proposed accessibility guidelines for running slope and cross slope''), not of a ramp: the ramp-versus-route boundary is unresolved in this corpus: TERM-001 is defined as the slope of a RAMP, this source measures the running slope of outdoor PATHS or trails, and no term holds route gradient. Extraction 49 already files REF-01003''s path slopes on parameter 3 (ramp gradient), so the same conflation is live in the evidence. Adjudicating this phrase onto TERM-001 would ratify it; minting a route-gradient term would imply extraction 49 is mis-filed. That is a judgment about the parameter''s scope, not about this phrase, and it is left for the batch that re-determines parameter 3.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (50, 48, 'DEFERRED', NULL, '''perceived difficulty'' would be a ramp-usability measure, but these are ratings of OUTDOOR PATHWAYS: the ramp-versus-route boundary is unresolved in this corpus: TERM-001 is defined as the slope of a RAMP, this source measures the running slope of outdoor PATHS or trails, and no term holds route gradient. Extraction 49 already files REF-01003''s path slopes on parameter 3 (ramp gradient), so the same conflation is live in the evidence. Adjudicating this phrase onto TERM-001 would ratify it; minting a route-gradient term would imply extraction 49 is mis-filed. That is a judgment about the parameter''s scope, not about this phrase, and it is left for the batch that re-determines parameter 3.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (51, 49, 'NAMES-EXISTING', 'TERM-001', '''ramp slope and height'' names two independent variables. The slope half is TERM-001 and is what this source''s extractions on parameter 3 concern; the height half is the rise, now level difference. One observation takes one outcome, so this row records TERM-001 and names the second concept here rather than writing a second row that would read as a contest.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (52, 50, 'NAMES-EXISTING', 'TERM-093', '''perceived discomfort while ascending and descending'' ramps is a measure of ramp usability, named in that term''s scope note. Adjudicated to it as an operationalisation.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (53, 51, 'NAMES-EXISTING', 'TERM-001', '''running slope'', located at REF-01005''s ramp objectives (''the maximum slopes that can be managed''), is the slope of a ramp -- the 1979 study''s whole ramp experiment varies it. TERM-001.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (54, 52, 'DEFERRED', NULL, '''marginal population'' names the SUBGROUP at the edge of capability whose needs set the design case (''steeper slopes present problems to subgroups within the total wheelchair population''). This project''s equivalent is the most-accommodating rule (owner directive 2026-07-21) -- a DOCTRINE, not a term -- and minting a term for it would put a doctrinal commitment into the vocabulary by the back door. Deferred to the owner, whose rule it is.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (55, 53, 'NAMES-EXISTING', 'TERM-053', '''limitations of stamina'' is reduced capacity for sustained activity, TERM-053''s definition. The source uses it as a GROUP label (''People with limitations of stamina ... may have difficulty with ramps steeper than 1:20''); TERM-053''s scope note forbids it as a population umbrella, so this adjudication names the mechanism, not a population.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (56, 54, 'DEFERRED', NULL, '''walking and reaching limitations'' names TWO functional limitations. The only terms for them are the functional-axis rows TERM-031 (Ambulant movement) and TERM-041 (Reach & manipulation), and the owner ruled ''axes'' a bad coined term on 2026-08-18; adjudicating onto them would harden a vocabulary the owner has criticised. The ICF lens is the ruled frame for functional limitation (CLAUDE.md section 6).', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (57, 55, 'NAMES-EXISTING', 'TERM-094', '''participatory accessibility audit'' is the accessibility audit method, run in partnership and -- in this source -- by field investigators who were all persons with disabilities. The accessibility audit term minted this batch names the method and its scope note records the participatory variant as the one that carries a Co-1 warrant.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (58, 56, 'DEFERRED', NULL, '''Community Based Participatory Research'' names the co-production methodology behind REF-01006''s Co-1 warrant, which the schema holds as evidence_sources.co1_source_type = ''participatory_research'': the concept IS held, but as a column vocabulary rather than a term (rule 5: one home). Minting a term for it would create a second home; adjudicating NOT-OURS would say it is not a concept of ours, which is false. Deferred until the term-versus-column placement is decided for held vocabularies.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (59, 57, 'DEFERRED', NULL, '''universal accessibility'' appears only as part of a standard''s title (''Harmonised Guidelines and Standards for Universal Accessibility in India (2021)''). Whether it means TERM-017 (universal design, usable by all without adaptation) or accessibility for persons with disabilities -- this project''s own reading of ''universal'' (CLAUDE.md section 9) -- cannot be settled from a title.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (60, 60, 'NOT-OURS', NULL, '''external accessibility'' is the label of one sub-scale of a 22-item questionnaire (eight items: sidewalk, floors, ramp, handrail, door). An instrument''s grouping of its items, not a concept; the items it groups are named separately.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (61, 61, 'NAMES-EXISTING', 'TERM-089', '''curb ramp'' is the object REF-01008 tested -- a short ramp through a curb. A narrower phrase for the ramp element (its level difference is the curb height, its run length 2-10 ft); adjudicated to the element rather than minted, per that term''s scope note.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (62, 62, 'NOT-OURS', NULL, '''handicapped pedestrians'' is the period''s UMBRELLA population label (1974-1980). It names no concept of ours: the doctrine forbids population umbrellas, and the groups the report actually sampled -- manual and electric wheelchair users, cane and crutch users, people with prosthetic limbs, elderly people -- are what the identity lens holds. The context sentence the observation carries uses ''handicapped people''; the source''s own ''handicapped pedestrians'' occurs in its acceptability discussion (''hazardous, for handicapped pedestrians, when they must use the ramp to enter or leave a street'').', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (63, 63, 'NAMES-EXISTING', 'TERM-089', '''short ramps'' is the ramp element qualified by length -- the class REF-01008''s recommendations are scoped to. Adjudicated to the ramp element; the length condition is ramp run length.', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:58', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (37, 65, 'tested_at', NULL, 'ramp 4: 1:12 over a 6 in curb, 6 ft run', 'own_sample', 'inferred', NULL, 'Ramps #1, 4, 5, 9, 10, 11, 12 and 13 are acceptable', NULL, '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (38, 66, 'tested_at', NULL, 'ramp 6: 1:10.67 over a 9 in curb, 8 ft run', 'own_sample', 'inferred', NULL, 'Ramps #2, 3, 6, 7, 8 are unacceptable', NULL, '2026-09-25 04:48', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa');